import React, { useState } from "react";
import { Link } from "react-router-dom";
// 1. Corregir la ruta de importación si es necesario, y asegurar que el nombre coincida
import HeaderLog from "../components/headerLog"; 

export default function Login() {
  const [correo, setCorreo] = useState("");
  const [contrasena, setContrasena] = useState("");

  const manejarLogin = () => {
    alert(`Aquí va tu conexión al backend.\nCorreo: ${correo}`);
  };

  return (
    <>
      <HeaderLog /> 

      <main>
        <form className="form-login">
          <h2 className="subtitulo">Iniciar sesión</h2>

          <label htmlFor="correo">Correo electrónico</label>
          <input
            type="email"
            id="correo"
            value={correo}
            onChange={(e) => setCorreo(e.target.value)}
            placeholder="Ingresa tu correo"
          />

          <label htmlFor="contrasena">Contraseña</label>
          <input
            type="password"
            id="contrasena"
            value={contrasena}
            onChange={(e) => setContrasena(e.target.value)}
            placeholder="Ingresa tu contraseña"
          />

          <button type="button" onClick={manejarLogin}>
            Ingresar
          </button>

          <div className="preguntas">
            <p><Link to="/registro">¿No tienes cuenta?</Link></p>
            <p><a href="#">¿Olvidó su contraseña?</a></p>
          </div>
        </form>
      </main>
    </>
  );
}
